function resetFiles(){objects.forEach(u=>URL.revokeObjectURL(u));objects=[]}
async function openComposer(m){editing=m?.id||null;files=structuredClone(m?.attachments||[]);resetFiles();$('#dialogLabel').textContent=m?(m.demo?'Пример материала · можно редактировать':'Твой материал'):'Новый материал';$('#title').value=m?.title||'';$('#body').value=m?.body||'';$('#source').value=m?.source||'';$('#openSource').hidden=!safeLink(m?.source);if(safeLink(m?.source))$('#openSource').href=m.source;$('#sourceWrap').hidden=!m?.source;$('#recordPanel').hidden=true;$('#composeStatus').textContent='';$('#files').value='';const reading=m?.section==='readings'||unitSection==='readings';$('#notesWrap').hidden=!reading;$('#readingDone').checked=!!m?.read;$('#readingDetails').open=!reading;$('#userNotes').value=m?.userNotes||'';$('#notesOriginal').hidden=!safeLink(m?.notesSource);if(safeLink(m?.notesSource))$('#notesOriginal').href=m.notesSource;$('#readingMeta').hidden=!reading||!m;$('#readingMeta').replaceChildren();if(reading&&m){for(const line of [m.citation,m.weeks?.length?'Недели '+m.weeks.join(', '):m.week?'Неделя '+m.week:'Неделя не уточнена'])if(line)$('#readingMeta').append(el('p','',line));if(m.weekBasis||m.readingSummary){const details=el('details');details.append(el('summary','','Источник и привязка к неделе'));for(const line of [m.weekBasis,m.readingSummary])if(line)details.append(el('p','',line));$('#readingMeta').append(details)}}$('#folder').replaceChildren(...[{id:'inbox',name:'Входящие'},...data.folders.filter(f=>f.type!=='year')].map(f=>{const o=el('option','',f.name);o.value=f.id;return o}));$('#folder').value=m?.folder||(data.folders.some(f=>f.id===view)?view:'inbox');renderFiles();dialog.showModal();setTimeout(()=>$('#title').focus(),0)}
async function renderFiles(){await dbReady;const container=$('#attachments');container.replaceChildren();for(const file of files){const row=el('div','attachment');row.append(el('span','',file.name+' · '+Math.max(1,Math.round(file.size/1024))+' КБ'));const actions=el('div');if(file.pending){actions.append(el('span','','Готов к сохранению'))}else if(db){const blob=await new Promise(resolve=>{const r=db.transaction('files').objectStore('files').get(file.id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve(null)});if(blob){const u=URL.createObjectURL(blob);objects.push(u);const a=el('a','','Скачать');a.href=u;a.download=file.name;actions.append(a)}}const remove=el('button','',' ×');remove.type='button';remove.setAttribute('aria-label','Убрать '+file.name);remove.onclick=()=>{files=files.filter(f=>f.id!==file.id);renderFiles()};actions.append(remove);row.append(actions);container.append(row)}}
