  const events=data.events.filter(e=>e.unit===unit.id);deadlineArea.append(list,calendar([...deadlines,...events]));panel.append(deadlineArea);renderSchedule(panel,unit);if(unit.importNotes){const note=el('details','source-notes');note.append(el('summary','','Примечания Moodle'),el('p','',unit.importNotes));panel.append(note)}return;
