const calendarNow=new Date();let calendarMonth=new Date(calendarNow.getFullYear(),calendarNow.getMonth(),1);const calendarToday=calendarNow.getFullYear()+'-'+String(calendarNow.getMonth()+1).padStart(2,'0')+'-'+String(calendarNow.getDate()).padStart(2,'0');
function calendar(deadlines){const wrap=el('section','calendar');const head=el('div','calendar-head');head.append(studyButton('‹',()=>{calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()-1,1);render()}),el('strong','',calendarMonth.toLocaleDateString('ru',{month:'long',year:'numeric'})),studyButton('›',()=>{calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+1,1);render()}));wrap.append(head);const grid=el('div','calendar-grid');for(const day of ['Пн','Вт','Ср','Чт','Пт','Сб','Вс'])grid.append(el('span','weekday',day));const y=calendarMonth.getFullYear(),m=calendarMonth.getMonth();const offset=(new Date(y,m,1).getDay()+6)%7;for(let i=0;i<offset;i++)grid.append(el('span'));for(let day=1;day<=new Date(y,m+1,0).getDate();day++){const date=y+'-'+String(m+1).padStart(2,'0')+'-'+String(day).padStart(2,'0');const matches=deadlines.filter(d=>d.date===date&&!d.done);const cell=el('span',matches.length?'calendar-day has-deadline':'calendar-day',String(day));if(matches.length)cell.title=matches.map(d=>d.title).join(', ');if(date===calendarToday)cell.classList.add('today');grid.append(cell)}wrap.append(grid);return wrap}
function wordCount(text){return text.trim()?text.trim().split(/\s+/u).length:0}
function renderEssay(panel,essay){
 const back=studyButton('‹ Все задания',()=>{essayId=null;render()},'subtle-button');panel.append(back);
 const editor=el('section','essay-editor');const title=el('input','essay-title');title.value=essay.title;title.setAttribute('aria-label','Название эссе');const status=el('span','essay-status','Сохранено');title.oninput=()=>{essay.title=title.value;essay.updated=new Date().toISOString();status.textContent=save()?'Сохранено':'Не сохранено'};editor.append(title);if(safeLink(essay.source))editor.append(studyLink(new URL(essay.source).hostname==='docs.google.com'?'Оригинал в Google Docs ↗':'Бриф в Moodle ↗',essay.source));
 const counter=el('span','word-counter',wordCount(essay.draft)+' слов');const top=el('div','essay-editor-meta');top.append(status,counter);editor.append(top);
 for(const [key,label,placeholder]of [['brief','Задание','Требования и критерии'],['plan','План','Структура и аргументы'],['research','Мои записи из Google Docs','Исследовательские заметки'],['draft','Черновик','Начни писать…'],['sources','Источники','Ссылки, цитаты и страницы']]){const labelEl=el('label','essay-field',label);const field=el('textarea',key==='draft'?'essay-draft':'');field.value=essay[key]||'';field.placeholder=placeholder;field.setAttribute('aria-label',label);field.oninput=()=>{essay[key]=field.value;essay.updated=new Date().toISOString();status.textContent=save()?'Сохранено':'Не сохранено';counter.textContent=wordCount(essay.draft)+' слов'};labelEl.append(field);if(key==='research'){const details=el('details','research-notes');details.append(el('summary','','Мои записи из Google Docs'),labelEl);editor.append(details)}else editor.append(labelEl)}panel.append(editor);
}
function openUnitSettings(unit){$('#unitForm').dataset.unit=unit.id;$('#moodleUrl').value=unit.moodleUrl||'';$('#unitSettings').showModal()}
$('#closeUnit').onclick=()=>$('#unitSettings').close();$('#unitForm').onsubmit=e=>{e.preventDefault();const url=new URL($('#moodleUrl').value);if(!['https:','http:'].includes(url.protocol)){$('#moodleUrl').setCustomValidity('Нужна ссылка https://');$('#moodleUrl').reportValidity();return}const unit=data.folders.find(f=>f.id===$('#unitForm').dataset.unit);unit.moodleUrl=url.href;if(save()){$('#unitSettings').close();render()}};$('#moodleUrl').oninput=()=>$('#moodleUrl').setCustomValidity('');
function openDeadline(unit){$('#deadlineForm').dataset.unit=unit.id;$('#deadlineForm').reset();$('#deadlineDialog').showModal()}
$('#closeDeadline').onclick=()=>$('#deadlineDialog').close();$('#deadlineForm').onsubmit=e=>{e.preventDefault();data.deadlines.push({id:crypto.randomUUID(),unit:$('#deadlineForm').dataset.unit,title:$('#deadlineName').value.trim(),date:$('#deadlineDate').value,done:false});if(save()){$('#deadlineDialog').close();render()}};
// A year opens its units, rather than a flat list of pages.


function safeLink(url){try{return ['http:','https:'].includes(new URL(url).protocol)}catch{return false}}
function matchesUnitSection(m){if(!data.folders.some(f=>f.id===view&&f.type==='unit'))return true;if(unitSection!=='readings')return m.section!=='readings';const weeks=m.weeks||[m.week].filter(Boolean);return m.section==='readings'&&(!notesOnly||!!m.userNotes?.trim())&&(!unreadOnly||!m.read)&&(!readingWeek||(readingWeek==='unknown'?!weeks.length:weeks.some(w=>String(w)===readingWeek)))}
function renderSchedule(panel,unit){const list=el('section','schedule');const events=data.events.filter(e=>e.unit===unit.id&&e.date>=calendarToday).sort((a,b)=>a.date.localeCompare(b.date)||(a.time||'').localeCompare(b.time||''));if(!events.length)return;const head=el('div','unit-section-head');head.append(el('h2','','Расписание'));if(events.length>6)head.append(studyButton(showAllEvents?'Свернуть':'Все занятия',()=>{showAllEvents=!showAllEvents;render()},'subtle-button'));list.append(head);for(const event of events.slice(0,showAllEvents?undefined:6)){const row=el('div','schedule-row');row.append(el('time','',new Date(event.date+'T12:00:00').toLocaleDateString('ru',{day:'numeric',month:'short'})+(event.time?' · '+event.time:'')));const description=el('div');description.append(el('strong','',event.title));if(event.note)description.append(el('p','',event.note));if(safeLink(event.source))description.append(studyLink('Moodle ↗',event.source));row.append(description);list.append(row)}panel.append(list)}
let importPayload=null,importUnit=null;
function openImport(unit){importUnit=unit.id;importPayload=null;$('#importFile').value='';$('#applyImport').disabled=true;$('#importPreview').textContent='Выбери снимок данных Moodle.';$('#importError').textContent='';$('#importDialog').showModal()}
$('#closeImport').onclick=()=>$('#importDialog').close();
$('#importFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024)throw Error('Файл слишком большой.');const p=JSON.parse(await file.text());if(p.format!=='jooka-moodle-v1'||p.unit?.id!==importUnit)throw Error('Файл предназначен для другого юнита.');for(const key of ['materials','deadlines','events','essays']){if(!Array.isArray(p[key])||p[key].length>500)throw Error('Неверный формат данных.');for(const item of p[key]){if(typeof item.id!=='string'||!item.id.startsWith('moodle-')||typeof item.title!=='string')throw Error('Неверная запись.');if(item.source&&!safeLink(item.source))throw Error('Неверная ссылка.');if(['deadlines','events'].includes(key)&&!/^\d{4}-\d{2}-\d{2}$/.test(item.date))throw Error('Неверная дата.')}}if(p.unit.moodleUrl&&!safeLink(p.unit.moodleUrl))throw Error('Неверная ссылка Moodle.');importPayload=p;$('#applyImport').disabled=false;$('#importPreview').textContent=p.materials.length+' материалов · '+p.events.length+' занятий · '+p.deadlines.length+' дедлайна · '+p.essays.length+' задания. '+(p.updateExisting?'Требования обновятся; черновики сохранятся.':'Существующие записи сохранятся.');$('#importError').textContent=''}catch(err){importPayload=null;$('#applyImport').disabled=true;$('#importError').textContent=err.message}};
$('#importForm').onsubmit=e=>{e.preventDefault();if(!importPayload)return;const p=importPayload;const previous=data;const {next,added}=mergeStudyImport(data,p,importUnit);data=next;if(!save()){data=previous;return}$('#importDialog').close();unitSection='overview';render();notify(p.updateExisting?'Данные обновлены':'Импортировано: '+added+' новых материалов')};
render();

// Persist edits to existing notes immediately; failed writes leave the saved record intact.
function autosaveMaterial(){
 const material=data.materials.find(m=>m.id===editing);if(!material)return;
 const before={...material};Object.assign(material,{title:$('#title').value,body:$('#body').value,userNotes:$('#userNotes').value,source:$('#source').value,read:$('#readingDone').checked,updated:new Date().toISOString()});
 if(save())$('#composeStatus').textContent='Сохранено';else{Object.assign(material,before);$('#composeStatus').textContent='Не сохранено — оставь окно открытым и скопируй текст.'}
}
for(const id of ['title','body','userNotes','source'])$('#'+id).addEventListener('input',autosaveMaterial);
$('#readingDone').addEventListener('change',autosaveMaterial);
dialog.addEventListener('close',render);
$('#exportNotes').onclick=()=>{
 const lines=['# жука — экспорт текстов',new Date().toLocaleString('ru'),'Вложения не включены.',''];
 for(const folder of [{id:'inbox',name:'Входящие'},...data.folders.filter(f=>f.type!=='year')]){
  const materials=data.materials.filter(m=>m.folder===folder.id&&!m.demo);const essays=Object.values(data.essays).filter(e=>e.unit===folder.id);if(!materials.length&&!essays.length)continue;
  lines.push('## '+folder.name,'');
  for(const m of materials){lines.push('### '+m.title,'',m.citation||'',m.weeks?.length?'Недели: '+m.weeks.join(', '):m.week?'Неделя: '+m.week:'',m.source||'',m.notesSource?'Google Docs: '+m.notesSource:'','',m.body||'',m.userNotes?'#### Мои заметки\n\n'+m.userNotes:'','')}
  for(const e of essays){lines.push('### '+e.title,'');for(const [key,label]of [['brief','Задание'],['plan','План'],['research','Исследование'],['draft','Черновик'],['sources','Источники']])if(e[key])lines.push('#### '+label,'',e[key],'')}
 }
 const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='jooka-notes-'+new Date().toISOString().slice(0,10)+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);notify('Тексты выгружены. Вложения остаются в библиотеке.');
};
